"""Minimal progress bars system (no tqdm dependency).

Each worker process reports its progress through a shared counter
(``multiprocessing.Value``) and the master process renders the aggregated bar
on stderr from its display loop.
"""

import multiprocessing
import sys

from .utils import terminal_columns


def is_notebook() -> bool:
    """Detect whether we are running inside a Jupyter notebook."""
    try:
        from IPython import get_ipython

        shell = get_ipython()
        if shell is None:
            return False
        return shell.__class__.__name__ == "ZMQInteractiveShell"
    except Exception:
        return False


class ProgressBars:
    """Aggregated progress bar fed by one shared counter per worker."""

    enabled = True

    def __init__(self, show_progress_bars: bool, nb_workers: int, total: int = None):
        # In a notebook there is no reliable carriage-return redraw: keep it
        # simple and stay silent there (no-op fallback).
        self.show_progress_bars = show_progress_bars and not is_notebook()
        self.nb_workers = nb_workers
        self.total = total if total is not None else nb_workers
        self.global_index = multiprocessing.Value("i", 0)
        self._values = [multiprocessing.Value("i", 0) for _ in range(nb_workers)]
        self._errors = []
        self._finished = False

    def get_next_value(self) -> int:
        """Called once by each worker to get its dedicated counter index."""
        with self.global_index.get_lock():
            index = self.global_index.value
            self.global_index.value += 1
        return index

    def update(self, index: int, value: int = 1) -> None:
        """Increment the progress counter of the given worker."""
        with self._values[index].get_lock():
            self._values[index].value += value

    def set_error(self, index: int, message: str = None) -> None:
        """Record that a worker hit an error."""
        self._errors.append((index, message))

    @property
    def errors(self):
        return list(self._errors)

    @property
    def value(self) -> int:
        return sum(counter.value for counter in self._values)

    def show(self) -> None:
        """Render the aggregated bar on stderr (master process only)."""
        if not self.show_progress_bars:
            return
        total = max(self.total, 1)
        value = min(self.value, total)
        percent = value / total
        columns = terminal_columns()
        prefix = "Progress: |"
        suffix = f"| {percent:6.1%} ({value}/{self.total})"
        bar_length = max(5, columns - len(prefix) - len(suffix) - 2)
        filled = int(bar_length * percent)
        bar = "#" * filled + "-" * (bar_length - filled)
        sys.stderr.write("\r" + prefix + bar + suffix)
        sys.stderr.flush()

    def finish(self) -> None:
        """Draw the final 100% bar and move to a new line."""
        if not self.show_progress_bars or self._finished:
            return
        self._finished = True
        self.show()
        sys.stderr.write("\n")
        sys.stderr.flush()


class NoProgressBars:
    """No-op replacement with the same interface as ProgressBars."""

    enabled = False
    global_index = None
    total = 0

    def get_next_value(self) -> int:
        return 0

    def update(self, index: int, value: int = 1) -> None:
        pass

    def set_error(self, index: int, message: str = None) -> None:
        pass

    @property
    def errors(self):
        return []

    @property
    def value(self) -> int:
        return 0

    def show(self) -> None:
        pass

    def finish(self) -> None:
        pass


def get_progress_bars(progress_bar: bool, nb_workers: int, total: int = None):
    """Factory used by core: real bars when requested, no-op otherwise."""
    if progress_bar:
        return ProgressBars(progress_bar, nb_workers, total=total)
    return NoProgressBars()

"""Generic chunking helpers and the DataType interface."""

from typing import Any, Dict, List, Tuple

import pandas as pd


def chunk_indices(nb_rows: int, nb_chunks: int) -> List[Tuple[int, int]]:
    """Split ``nb_rows`` rows into at most ``nb_chunks`` contiguous chunks.

    Returns a list of ``(start, end)`` bounds. Never returns empty chunks
    (except when ``nb_rows == 0``, which yields a single ``(0, 0)`` chunk).
    """
    nb_chunks = max(1, nb_chunks)
    if nb_rows <= 0:
        return [(0, 0)]
    nb_chunks = min(nb_chunks, nb_rows)
    base, remainder = divmod(nb_rows, nb_chunks)
    bounds = []
    start = 0
    for index in range(nb_chunks):
        size = base + (1 if index < remainder else 0)
        bounds.append((start, start + size))
        start += size
    return bounds


def groupby_keys(groupby) -> list:
    """Group keys of a (Series|DataFrame)GroupBy, in apply order."""
    return list(groupby.groups.keys())


def groupby_names(groupby) -> list:
    """Names of the grouping levels."""
    return list(groupby._grouper.names)


def concat_grouped_results(keys: list, results: list, names: list):
    """Reassemble per-group results like ``groupby.apply`` does.

    - all scalars -> Series indexed by the group keys
    - Series/DataFrame results -> concatenated with a group-keys outer level
    """
    if all(not isinstance(result, (pd.Series, pd.DataFrame)) for result in results):
        if len(names) == 1:
            index = pd.Index(keys, name=names[0])
        else:
            tuples = [key if isinstance(key, tuple) else (key,) for key in keys]
            index = pd.MultiIndex.from_tuples(tuples, names=names)
        return pd.Series(list(results), index=index)
    return pd.concat(dict(zip(keys, results)), names=names)


def rolling_kwargs(rolling) -> Dict[str, Any]:
    """Constructor kwargs needed to rebuild an equivalent Rolling object."""
    kwargs = {}
    for attribute in (
        "window",
        "min_periods",
        "center",
        "win_type",
        "closed",
        "step",
        "method",
    ):
        if hasattr(rolling, attribute):
            kwargs[attribute] = getattr(rolling, attribute)
    return kwargs


def expanding_kwargs(expanding) -> Dict[str, Any]:
    """Constructor kwargs needed to rebuild an equivalent Expanding object."""
    kwargs = {}
    for attribute in ("min_periods", "method"):
        if hasattr(expanding, attribute):
            kwargs[attribute] = getattr(expanding, attribute)
    return kwargs


class DataType:
    """Interface implemented by every supported pandas data type."""

    @staticmethod
    def get_chunks(nb_workers: int, data, func_args: tuple, func_kwargs: dict) -> list:
        """Split ``data`` into a list of chunks (one work unit per chunk)."""
        raise NotImplementedError

    @staticmethod
    def work(chunk, func, func_args: tuple, func_kwargs: dict):
        """Apply the user function to a single chunk (runs in a worker)."""
        raise NotImplementedError

    @staticmethod
    def reduce(chunks_results: list, data, func_args: tuple, func_kwargs: dict):
        """Combine per-chunk results into the final pandas object."""
        raise NotImplementedError

"""DataFrame parallel_apply (chunked by axis) and parallel_applymap."""

import pandas as pd

from .generic import DataType, chunk_indices


class DataFrameApply(DataType):
    @staticmethod
    def get_chunks(nb_workers, df, func_args, func_kwargs):
        axis = func_kwargs.get("axis", 0)
        if axis in (1, "columns"):
            # func sees entire rows: chunk along rows.
            bounds = chunk_indices(df.shape[0], nb_workers)
            return [df.iloc[start:end] for start, end in bounds]
        # func sees entire columns: chunk along columns.
        bounds = chunk_indices(df.shape[1], nb_workers)
        return [df.iloc[:, start:end] for start, end in bounds]

    @staticmethod
    def work(chunk, func, func_args, func_kwargs):
        return chunk.apply(func, args=func_args, **func_kwargs)

    @staticmethod
    def reduce(chunks_results, df, func_args, func_kwargs):
        axis = func_kwargs.get("axis", 0)
        if axis in (1, "columns"):
            return pd.concat(chunks_results, copy=False)
        first = chunks_results[0]
        if isinstance(first, pd.DataFrame):
            # func returned a Series/DataFrame per column: same rows, more columns.
            return pd.concat(chunks_results, axis=1, copy=False)
        # func returned a scalar per column: Series over the columns.
        return pd.concat(chunks_results, copy=False)


class DataFrameApplyMap(DataType):
    @staticmethod
    def get_chunks(nb_workers, df, func_args, func_kwargs):
        bounds = chunk_indices(df.shape[0], nb_workers)
        return [df.iloc[start:end] for start, end in bounds]

    @staticmethod
    def work(chunk, func, func_args, func_kwargs):
        # DataFrame.applymap is deprecated in pandas >= 2.1 in favor of map.
        if hasattr(chunk, "map"):
            return chunk.map(func, **func_kwargs)
        return chunk.applymap(func, **func_kwargs)

    @staticmethod
    def reduce(chunks_results, df, func_args, func_kwargs):
        return pd.concat(chunks_results, copy=False)

"""Series parallel_apply and parallel_map (chunked by rows)."""

import pandas as pd

from .generic import DataType, chunk_indices


class SeriesApply(DataType):
    @staticmethod
    def get_chunks(nb_workers, series, func_args, func_kwargs):
        bounds = chunk_indices(series.shape[0], nb_workers)
        return [series.iloc[start:end] for start, end in bounds]

    @staticmethod
    def work(chunk, func, func_args, func_kwargs):
        return chunk.apply(func, args=func_args, **func_kwargs)

    @staticmethod
    def reduce(chunks_results, series, func_args, func_kwargs):
        return pd.concat(chunks_results, copy=False)


class SeriesMap(SeriesApply):
    @staticmethod
    def work(chunk, func, func_args, func_kwargs):
        return chunk.map(func, *func_args, **func_kwargs)

"""DataFrameGroupBy / SeriesGroupBy parallel_apply (chunked by group keys)."""

from .generic import DataType, chunk_indices, concat_grouped_results, groupby_keys, groupby_names


class GroupByApply(DataType):
    @staticmethod
    def get_chunks(nb_workers, groupby, func_args, func_kwargs):
        keys = groupby_keys(groupby)
        chunks = []
        for start, end in chunk_indices(len(keys), nb_workers):
            chunks.append([(key, groupby.get_group(key)) for key in keys[start:end]])
        return chunks

    @staticmethod
    def work(chunk, func, func_args, func_kwargs):
        return [(key, func(group, *func_args, **func_kwargs)) for key, group in chunk]

    @staticmethod
    def reduce(chunks_results, groupby, func_args, func_kwargs):
        items = [item for chunk in chunks_results for item in chunk]
        keys = [key for key, _ in items]
        results = [result for _, result in items]
        return concat_grouped_results(keys, results, groupby_names(groupby))

"""RollingGroupby parallel_apply (chunked by group keys)."""

from .generic import (
    DataType,
    chunk_indices,
    concat_grouped_results,
    rolling_kwargs,
)


class RollingGroupByApply(DataType):
    @staticmethod
    def get_chunks(nb_workers, rolling_groupby, func_args, func_kwargs):
        grouper = rolling_groupby._grouper
        obj = rolling_groupby.obj
        kwargs = rolling_kwargs(rolling_groupby)
        indices = grouper.indices  # {group key: integer positions into obj}
        keys = list(indices.keys())
        chunks = []
        for start, end in chunk_indices(len(keys), nb_workers):
            items = [(key, obj.iloc[indices[key]]) for key in keys[start:end]]
            chunks.append((items, kwargs))
        return chunks

    @staticmethod
    def work(chunk, func, func_args, func_kwargs):
        items, kwargs = chunk
        return [
            (key, group.rolling(**kwargs).apply(func, *func_args, **func_kwargs))
            for key, group in items
        ]

    @staticmethod
    def reduce(chunks_results, rolling_groupby, func_args, func_kwargs):
        items = [item for chunk in chunks_results for item in chunk]
        keys = [key for key, _ in items]
        results = [result for _, result in items]
        return concat_grouped_results(keys, results, list(rolling_groupby._grouper.names))

