"""Series.rolling parallel_apply (chunked by rows with window overlap)."""

import pandas as pd

from .generic import DataType, chunk_indices, rolling_kwargs


class SeriesRollingApply(DataType):
    @staticmethod
    def get_chunks(nb_workers, rolling, func_args, func_kwargs):
        obj = rolling.obj
        kwargs = rolling_kwargs(rolling)
        window = kwargs.get("window")
        nb_rows = len(obj)

        if not isinstance(window, int) or window < 1:
            # Time-based (offset) windows cannot be safely overlapped:
            # fall back to a single chunk.
            return [(obj, kwargs, 0, nb_rows)]

        center = bool(kwargs.get("center"))
        left = window // 2 if center else window - 1
        right = (window - 1 - window // 2) if center else 0

        chunks = []
        for start, end in chunk_indices(nb_rows, nb_workers):
            ext_start = max(0, start - left)
            ext_end = min(nb_rows, end + right)
            # Each chunk keeps the rows it needs to compute its own window
            # values, and remembers which slice of the result to keep.
            chunks.append((obj.iloc[ext_start:ext_end], kwargs, start - ext_start, end - ext_start))
        return chunks

    @staticmethod
    def work(chunk, func, func_args, func_kwargs):
        part, kwargs, keep_start, keep_end = chunk
        result = part.rolling(**kwargs).apply(func, *func_args, **func_kwargs)
        return result.iloc[keep_start:keep_end]

    @staticmethod
    def reduce(chunks_results, rolling, func_args, func_kwargs):
        return pd.concat(chunks_results, copy=False)
